def Saisie():
    b = False
    while not b:
        n = int(input('Donner n: '))
        b = n >= 4 and n % 2 == 0
    return n


def premier(x):
    b = x > 1
    d = 1
    while b and d <= x // 2:
        d += 1
        b = x % d != 0
    return b


def couples_premiers(Nb):
    R = ''
    for i in range(Nb):
        for j in range(Nb):
            if premier(i) and premier(j) and i + j == Nb:
                R += '(' + str(i) + ',' + str(j) + ')'
    return R


###############PP##################
Nb = Saisie()
couples = couples_premiers(Nb)
print(couples)

